\begin{theorem}%
  \label{thm:alternating-rate-stoch}
  Let in addition to the assumptions of Theorem~\ref{thm:alternating-rate} also Assumption~\ref{ass:unbiased} and~\ref{ass:bounded-variance} hold true. For algorithm~\eqref{eq:gda-non-strongly-stoch} with step sizes
  \begin{equation*}
  \eta_x = \min \left\{\frac{\epsilon^2}{\rho(L^2+\sigma^2)}, \frac{\epsilon^4}{\rho^2 L(L+L_f+\sigma)D_h^2 L_{\nabla\Phi}}, \frac{\epsilon^6}{\rho^3L(L+L_f+\sigma)\sigma^2D_h^2 }\right\},
  \end{equation*}
  $\eta_y= \min\{\frac{1}{2 L_{\nabla\Phi}}, \frac{\epsilon^2}{\rho \sigma^2}\}$ and $\lambda=\frac{1}{2\rho}$ the number of stochastic gradient evaluations $K$ required is
  % iterates generated by~\eqref{eq:gda-non-strongly-stoch} with $\eta_y=\mathcal{O}(\epsilon^2)\le \nicefrac{1}{2L_{\nabla\Phi}}$, $\eta_x=\mathcal{O}(\epsilon^6)<\nicefrac{1}{2\rho}$ and $\lambda=\nicefrac{1}{2\rho}$ fulfill
  \begin{equation*}
      \mathcal{O}\left(\frac{\Delta^*(L^2+L_f^2+\sigma^2)\rho}{\epsilon^4}\max\Big\{1, \frac{\rho L_{\nabla\Phi}LD_h^2}{\epsilon^2}, \frac{\rho^2 D_h^2 \sigma^2}{\epsilon^4}\Big\}+ \frac{\Delta_0\rho}{\epsilon^2}\right),
  \end{equation*}
  where $\Delta^* = \psi(x_0) - \inf_{x\in\R^d} \psi(x)$ and $\Delta_0=\psi(x_0)-\Psi(x_0,y_0)$, to visit an $\epsilon$-stationary point in expectation such that $\min_{1\le k \le K}\E[\Vert \nabla \psi_\lambda(x_k) \Vert] \le \epsilon$.
\end{theorem}

