\begin{lemma}[{see~\cite[Theorem 3.52]{mordukhovich-variational-analysis}}]%
  \label{lem:lipschitz-bounded-subgradients}
  For an $L_\psi$-Lipschitz continuous function $\psi:\R^d \to \R$ every Fr\'echet subgradient is bounded in norm by $L_\psi$.
\end{lemma}

\begin{lemma}[{see~\cite[Lemma 2.2]{stoch_weakly_model_based}}]%
  \label{lem:grad_smooth_is_prox}
  Let $\psi: \R^d \to \R\cup\{+\infty\}$ be a proper, $\rho$-weakly convex, and l.s.c.\ function, and let $\lambda \in (0,\rho^{-1})$. Then the Moreau envelope $\psi_\lambda$ is continuously differentiable
  on $\R^d$ with gradient
  \begin{equation*}
    \nabla \psi_\lambda(x) = \frac{1}{\lambda}\left(x - \prox{\lambda \psi}{x}\right) \quad \mbox{for all $x \in \R^d$},
  \end{equation*}
  and this gradient is Lipschitz continuous.
\end{lemma}

\begin{proposition}[Subgradient characterization of the max function]%
  \label{thm:extended-danskin}
  Let Assumption~\ref{ass:weakly-convex-gradient-lipschitz} and~\ref{ass:regularizers} hold true.
  Then, the function $\phi$, see~\eqref{eq:max-function}, fulfills
  \begin{equation*}
    \partial [\Phi(\cdot,y^*)](x) \subseteq \partial\phi(x) \quad \forall y^*\in Y(x), \forall x\in \R^d.
  \end{equation*}
  In particular, $\phi$ is $\rho$-weakly convex.
\end{proposition}

\begin{proof}
  From the $\rho$-weak convexity of $\Phi(\cdot,y)$, we have that $\Phi(\cdot,y) + \frac{\rho}{2} \|\cdot\|^2$ is convex for all $y\in\R^n$. We define $\tilde{\Phi}(x,y) = \Phi(x,y) + \frac\rho2 \|x\|^2$ and $\tilde{\Gamma}(x,y) = \Gamma(x,y)+\frac{\rho}{2}\Vert x \Vert^2$ for $(x,y)\in\R^d\times\R^n$ as well as
  \begin{equation*}
    \tilde{\phi}(x) = \max_{y \in \R^n} \tilde{\Gamma}(x,y) = \phi(x) + \frac{\rho}{2} \|x\|^2.
  \end{equation*}
  Notice that $\tilde{\Gamma}(x,\cdot)$ is concave for any $x \in \R^d$ and $\tilde{\Gamma}(\cdot,y)$ is convex for any $y \in \R^n$.
  Thus, the function $\tilde{\phi}$ is convex and $\dom \tilde{\phi} = \dom \phi = \R^d$. Therefore $\phi$ is continuous, which implies that $\partial \phi(x) \neq \emptyset$ for any $x \in \R^d$.
  Let $x \in \R^d$, $y \in Y(x)$ and $v \in \R^d$. For any $\alpha >0$ it holds
  \begin{equation*}
    \frac{\tilde{\phi}(x+\alpha v) - \tilde{\phi}(x)}{\alpha} \geq \frac{\tilde{\Gamma}(x+\alpha v, y) - \tilde{\Gamma}(x,y)}{\alpha} =  \frac{\tilde{\Phi}(x+\alpha v, y) - \tilde{\Phi}(x,y)}{\alpha},
  \end{equation*}
  thus
  \begin{equation}
    \begin{aligned}
      \tilde{\phi}'(x;v) &= \inf_{\alpha >0} \frac{\tilde{\phi}(x+\alpha v) - \tilde{\phi}(x)}{\alpha} \geq \inf_{\alpha >0} \frac{\tilde{\Phi}(x+\alpha v, y) - \tilde{\Phi}(x,y)}{\alpha} = [\tilde{\Phi}(\cdot,y)]'(x;v),
    \end{aligned}
  \end{equation}
  where $[\Phi(\cdot,y)]'(x;v)$ denotes the directional derivative of $\Phi$ in the first component at $x$ in the direction $v$.
  In conclusion,
  \begin{equation}
    \label{eq1}
    \tilde{\phi}'(x;v) \geq \sup_{y \in Y(x)}  [\tilde{\Phi}(\cdot,y)]'(x;v) \quad \forall v \in \R^d
  \end{equation}
  and for $y\in Y(x)$ we therefore conclude $\partial [\tilde{\Phi}(\cdot,y)](x) \subseteq \partial\tilde{\phi}(x)$.
  The first statement is obtained by subtracting $\rho x$ on both sides of the inclusion.
\end{proof}

\begin{lemma}[Lipschitz continuity of the max function]%
  \label{lem:max-is-lipschitz}
  The Lipschitz continuity of $\Phi$ in its first component implies that $\phi$ is Lipschitz with the same constant.
\end{lemma}

\begin{proof}
  Let $x,x' \in \R^d$ and $y^*\in Y(x)$. On the one hand
  \begin{equation*}
    \begin{aligned}
      \phi(x) - \phi(x') &= \Phi(x,y^*)-h(y^*) - \phi(x')\\
                        &\le \Phi(x,y^*)-h(y^*) - \Phi(x',y^*)+h(y^*)\le L \Vert x-x' \Vert.
    \end{aligned}
  \end{equation*}
  The reverse direction $\phi(x') - \phi(x) \le L\Vert x-x' \Vert$ follows analogously.
\end{proof}

\begin{lemma}%
  \label{lem:xhatk-as-prox}
  For any $\lambda\in(0,\rho^{-1})$ and all $k\ge0$ the point $\hat{x}_k := \prox{\lambda g}{x_k}$ can also be written for some $v_k\in \partial \phi(\hat{x}_k)$ as
  \begin{equation*}
    \hat{x}_k = \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + (1-\eta_x\lambda^{-1})\hat{x}_k}.
  \end{equation*}
\end{lemma}

\begin{proof}
  Let $k\ge0$ be arbitrary but fixed and recall that $g=f+\phi$. By the definition of $\hat{x}_k$ we have that
  \begin{equation*}
      0 \in \partial \psi(\hat{x}_k) + \frac1\lambda(\hat{x}_k-x_k) = \partial(\phi+f)(\hat{x}_k) + \frac1\lambda(\hat{x}_k-x_k).
  \end{equation*}
  % TODO: reference
  We can estimate through the continuity of $\phi$ and subdifferential calculus
  \begin{equation*}
    \frac1\lambda(x_k - \hat{x}_k) \in \partial(\phi+f)(\hat{x}_k) \subseteq \partial \phi(\hat{x}_k) + \partial f(\hat{x}_k).
  \end{equation*}
  Thus, there exists $v_k \in \partial \phi(\hat{x}_k)$ such that $\frac1\lambda (x_k - \hat{x}_k) \in v_k + \partial f(\hat{x}_k)$.
  % \begin{equation*}
  %   \frac1\lambda (x_k - \hat{x}_k) \in v_k + \partial f(\hat{x}_k).
  % \end{equation*}
  Also,
  \begin{equation*}
    \begin{aligned}
      \frac1\lambda(x_k - \hat{x}_k) \in  \partial f(\hat{x}_k) +  v_k &\Leftrightarrow \frac{\eta_x }{\lambda}x_k - \eta_x v_k + (1-\frac{\eta_x}{\lambda})\hat{x}_k \in \hat{x}_k + \eta_x \partial f(\hat{x}_k) \\
      &\Leftrightarrow \hat{x}_k = \prox{\eta_x f}{\frac{\eta_x}{\lambda}x_k - \eta_x v_k + \big(1-\frac{\eta_x}{\lambda}\big)\hat{x}_k}.
    \end{aligned}
  \end{equation*}
\end{proof}

\begin{lemma}%
  \label{lem:descent-on-moreau}
  With $\lambda = \nicefrac{1}{2\rho}$ and $\eta_x \ge 0$ we have for all $k\ge0$ that
  \begin{equation*}
    \psi_\lambda(x_{k+1}) \le \psi_\lambda(x_k) + 2\rho\eta_x\Delta_k - \frac12\eta_x \Vert \nabla \psi_\lambda(x_k) \Vert^2  + 4\rho\eta_x^2L^2,
  \end{equation*}
  where $\Delta_k := \psi(x_k) - \Psi(x_k, y_k) \ge 0$.
\end{lemma}

\begin{proof}
  Let $k\ge0$ be fixed. As before we denote $\hat{x}_k = \prox{\lambda \psi}{x_k}$. From the definition of the Moreau envelope we have that
  \begin{equation}
    \label{eq:moreau-is-min}
    \psi_\lambda(x_{k+1}) = \min_{x\in\R^d} \Big\{ \psi(x) + \frac{1}{2\lambda} \Vert x - x_{k+1} \Vert^2\Big\} \le \psi(\hat{x}_k) + \frac{1}{2\lambda} \Vert \hat{x}_k - x_{k+1} \Vert^2.
  \end{equation}
  Let now $v_k \in \partial\phi(\hat{x}_k)$ as in Lemma~\ref{lem:xhatk-as-prox}. We successively deduce for $\beta:=1-\eta_x \lambda^{-1}$
  \begin{align}
    \Vert \hat{x}_k - x_{k+1} \Vert^2 &= \Vert \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + \beta\hat{x}_k} - \prox{\eta_x f}{x_k - \eta_x g_k}\Vert^2 \label{eq:defin-iter}\\
     &\le \Vert \beta(\hat{x}_k - x_k) + \eta_x (g_k - v_k)\Vert^2 \label{eq:1-Lipschitz}\\
     &= {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x\beta\langle g_k-v_k, \hat{x}_k - x_k\rangle
     + \eta_x^2\Vert g_k - v_k \Vert^2 \notag\\
     &\le {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x \beta\langle g_k-v_k, \hat{x}_k - x_k\rangle + 4\eta_x^2L^2 \label{eq:Lipschitz}
  \end{align}
  where~\eqref{eq:defin-iter} uses Lemma~\ref{lem:xhatk-as-prox} and the definition of $x_{k+1}$, inequality~\eqref{eq:1-Lipschitz} holds because of the nonexpansiveness of the proximal operator, and~\eqref{eq:Lipschitz} follows from the Lipschitz continuity of $\Phi$ and $\phi$ (see Lemma~\ref{lem:max-is-lipschitz}) and the fact that Lipschitz continuity implies bounded subgradients.
  We are left with estimating the inner product in the above inequality and we do so by splitting it into two:
  first of all, from the weak convexity of $\Phi$ in $x$ we have that
  \begin{equation*}
    \begin{aligned}
      \langle g_k, \hat{x}_k - x_k \rangle &\le \Phi(\hat{x}_k, y_k) - \Phi(x_k, y_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2 \\
      % &= \Phi(\hat{x}_k, y_k)-h(y_k) - (\Phi(x_k, y_k)-h(y_k)) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2\\
      &\le \phi(\hat{x}_k) - \Gamma(x_k,y_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2.
    \end{aligned}
  \end{equation*}
  Secondly, by the $\rho$-weak convexity of $\phi$
  \begin{equation*}
    -\langle v_k, \hat{x}_k - x_k\rangle \le \phi(x_k) - \phi(\hat{x}_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2.
  \end{equation*}
  Combining the last two inequalities we get that
  \begin{equation}
    \label{eq:estimate-middle}
    \langle g_k-v_k, \hat{x}_k - x_k\rangle \le \phi(x_k) - \Gamma(x_k,y_k) + \rho \Vert \hat{x}_k - x_k \Vert^2.
  \end{equation}
  Plugging~\eqref{eq:estimate-middle} into~\eqref{eq:Lipschitz} we deduce
  \begin{equation}
    \begin{aligned}
    \label{eq:ab3}
    \Vert \hat{x}_k - x_{k+1} \Vert^2 \le \underbrace{[{(1-\eta_x\lambda^{-1})}^2+2\eta_x(1-\eta_x \lambda^{-1})\rho]}_{= (*)} \Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x \Delta_k + 4\eta_x^2L^2, \\
    % &\le \Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x\Delta_k -2\eta_x\rho \Vert\hat{x}_k - x_k \Vert^2  + 2\eta_x^2 L^2
    \end{aligned}
  \end{equation}
  where we used the fact that $1-\beta\le1$ in the factor of $\Delta_k$.
  Now note that
  \begin{equation}
    \label{eq:terrible-algebra}
    \begin{aligned}
      (*) &= 1 - 2\eta_x \lambda^{-1} + \eta_x^2 \lambda^{-2} + 2\eta_x\rho - 2\eta_x^2 \lambda^{-1}\rho\\
      &= 1 - 4\eta_x\rho + 4 \eta_x^2\rho^2 + 2\eta_x\rho - 4 \eta_x^2\rho^2 = 1-2\eta_x\rho.
    \end{aligned}
  \end{equation}
  Combining~\eqref{eq:moreau-is-min},~\eqref{eq:ab3} and~\eqref{eq:terrible-algebra} we deduce, using $\lambda=\nicefrac{1}{2\rho}$,
  % a lot of algebra happens here but it's correct
  \begin{equation*}
    \label{eq:descent-moreau}
    \begin{aligned}
      \psi_\lambda(x_{k+1}) &\le \psi(\hat{x}_k) + \frac{1}{2\lambda} \left(\Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x\Delta_k -2\eta_x\rho \Vert\hat{x}_k - x_k \Vert^2  + 4\eta_x^2L^2\right) \\
      &= \psi_\lambda(x_k) + 2\rho\eta_x\Delta_k - \frac12\eta_x \Vert \nabla \psi_\lambda(x_k) \Vert^2  + 4\rho\eta_x^2L^2.
    \end{aligned}
  \end{equation*}
  % where we used that $\lambda=\nicefrac{1}{2\rho}$.
\end{proof}

