\begin{lemma}%
  \label{lem:estimate-Delta}
  We have that for all $1 \le m \le k$,
  \begin{equation}
    \begin{aligned}
      \label{eq:estimate-Delta}
      \Delta_k \le 2\eta_x L(L+L_f)(k-m) + \frac{1}{2\eta_y} \Big(\Vert y_{k-1} - y^*_m \Vert^2 - \Vert y_k - y^*_m \Vert^2 \Big).
    \end{aligned}
  \end{equation}
\end{lemma}

\begin{proof}
  % Let $1\le m \le k$ be fixed.
  Plugging $y=y^*_m$ into~\eqref{eq:gradient-ascent-estimation} we deduce that
  \begin{equation}
    \label{eq:standard_descent_with_ystar}
    \begin{aligned}
       0 \le \Psi(x_k, y_k) - \Psi(x_k, y^*_m) + \frac{1}{2\eta_y} \Big(\Vert y^*_m - y_{k-1} \Vert^2 - \Vert y^*_m - y_k \Vert^2 \Big).
    \end{aligned}
  \end{equation}
  Starting from the definition of $\Delta_k = \Psi(x_k,y^*_k) - \Psi(x_k,y_k)$, we add~\eqref{eq:standard_descent_with_ystar} to obtain
  \begin{equation}
    \label{eq:diff-function-values}
    \begin{aligned}
      \Delta_k %&= \Psi(x_k,y^*_k) - \Psi(x_k,y_k) \\
      &\le \Psi(x_k,y^*_k) - \Psi(x_k,y_m^*) + \frac{1}{2\eta_y} \Big(\Vert y^*_m - y_{k-1} \Vert^2 - \Vert y^*_m - y_k \Vert^2 \Big).
    \end{aligned}
  \end{equation}
  Due to the Lipschitz continuity of $\Phi$, terms which only differ in their first argument will be easy to estimate. Therefore, we insert and subtract $\Phi(x_m,y_{k}^*)$ to deduce
  \begin{equation}
    \label{eq:plus-minus-functionval}
    \begin{aligned}
      \MoveEqLeft \Psi(x_k, y^*_k) - \Psi(x_k, y^*_m)  \\ %&= \Phi(x_k, y^*_k)-h(y^*_k) - \Phi(x_k, y^*_m)+h(y^*_m) \\
      &= \Phi(x_k, y^*_k) - \Phi(x_m, y^*_k) + \Phi(x_m, y^*_k)-h(y^*_k) - \Phi(x_k, y^*_m) + h(y^*_m) \\
      &\le \Phi(x_k, y^*_k) - \Phi(x_m, y^*_k) + \Phi(x_m, y^*_m)-h(y^*_m) - \Phi(x_k, y^*_m) + h(y^*_m)\\
      &= \Phi(x_k,y^*_k) - \Phi(x_m,y^*_k) + \Phi(x_m,y^*_m) - \Phi(x_k, y^*_m).
    \end{aligned}
  \end{equation}
  We estimate the above expression for $k>m$ by making use of the Lipschitz continuity of $\Phi(\cdot, y)$ and~\eqref{eq:bound-prox-f} deducing
  \begin{equation}
    \label{eq:fun-val-same-y}
    \begin{aligned}
      \MoveEqLeft \Phi(x_k, y^*_k) - \Phi(x_m, y^*_k)  \le L \Vert x_k - x_m \Vert \le L \sum_{l=m}^{k-1} \Vert x_{l+1}-x_l \Vert \\
      &\le L \sum_{l=m}^{k-1} \Big( \Vert \prox{\eta_x f}{x_l -\eta_x g_l} - \prox{\eta_x f}{x_l} \Vert + \Vert \prox{\eta_x f}{x_l} - x_l \Vert \Big)\\
      & \le \eta_x L(L+L_f)(k-m).
    \end{aligned}
  \end{equation}
  For $k=m$ the inequality follows trivially. Analogously, we deduce
  \begin{equation}
    \label{eq:fun-val-same-y-2}
      \Phi(x_m, y^*_m) - \Phi(x_k, y^*_m) \le \eta_x L(L+L_f)(k-m).
  \end{equation}
  Plugging~\eqref{eq:plus-minus-functionval},~\eqref{eq:fun-val-same-y} and~\eqref{eq:fun-val-same-y-2} into~\eqref{eq:diff-function-values} gives the statement of the lemma.
\end{proof}

\begin{lemma}%
  \label{lem:estimate-sum-of-delta}
  It holds that for all $K\ge1$
  \begin{equation}
    \label{eq:estimate-sum-of-delta}
    \frac{1}{K} \sum_{k=0}^{K-1} \Delta_k \le \eta_x L(L+L_f) B + \frac{L_{\nabla\Phi}D_h^2}{2B} + \frac{\Delta_0}{K}.
  \end{equation}
\end{lemma}

\begin{proof}
  By splitting the summation into blocks we get that
  \begin{equation}
    \label{eq:split--summation-into-blocks}
    \sum_{k=0}^{K-1} \Delta_k  = \sum_{j=0}^{K/B-1} \ \sum_{k=jB}^{(j+1)B-1} \Delta_k.
  \end{equation}
  By using~\eqref{eq:estimate-Delta} from Lemma~\ref{lem:estimate-Delta} with $j>0$ and $m=jB$ and the fact that $\sum_{k=1}^{B-1} k \le \nicefrac{B^2}{2}$ we have
  \begin{equation}
    \label{eq:sum-over-any-block}
    \begin{aligned}
      \sum_{k=jB}^{(j+1)B-1} \Delta_k &\le \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y} \Vert y_{jB-1}-y^*_{jB} \Vert^2 \\
      % &\le \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y}D_h^2,
    \end{aligned}
  \end{equation}
  where the last term can be bounded by $D_h^2$, which was defined in Assumption~\ref{ass:regularizers} and denotes the diameter of $\dom h$.
  We do the same for the case $j=0$ but choose here $m=1$ and have separate out the first summand of $\sum_{k=0}^{B-1} \Delta_k$ as Lemma~\ref{lem:estimate-Delta} does not hold for $k=0$ and therefore get an extra $\Delta_0$ summand.
  % with $m=1$ and the fact that $\sum_{k=1}^{B-1} k \le \nicefrac{B^2}{2}$ we get that
  % \begin{equation}
  %   \label{eq:sum-first-block}
  %   \begin{aligned}
  %     \sum_{k=0}^{B-1} \Delta_k &\le \Delta_0 + \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y} \Vert y_{0}-y^*_{1} \Vert^2 \\
  %     &\le \Delta_0 + \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y}D_h^2,
  %   \end{aligned}
  % \end{equation}
  where $D_h$ was defined in Assumption~\ref{ass:regularizers} and denotes the diameter of $\dom h$.
  % Analogously, for $j>0$ and $m=jB$ we have that
  % \begin{equation}
  %   \label{eq:sum-over-any-block}
  %   \begin{aligned}
  %     \sum_{k=jB}^{(j+1)B-1} \Delta_k &\le \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y} \Vert y_{jB-1}-y^*_{jB} \Vert^2 \\
  %     &\le \eta_x L(L+L_f) B^2 + \frac{1}{2\eta_y}D_h^2.
  %   \end{aligned}
  % \end{equation}
  Plugging~\eqref{eq:sum-over-any-block} into~\eqref{eq:split--summation-into-blocks} gives
  \begin{equation*}
    % \label{eq:sum-over-all}
    \frac{1}{K} \sum_{k=0}^{K-1} \Delta_k \le \eta_x L(L+L_f) B + \frac{1}{2\eta_y B}D_h^2 + \frac{\Delta_0}{K}.
  \end{equation*}
  The desired statement is obtained by using the step size $\eta_y=\nicefrac{1}{L_{\nabla\Phi}}$.
\end{proof}

\begin{lemma}%
  \label{lem:stoch-descent-on-moreau}
  With $\lambda = \nicefrac{1}{2\rho}$ we have for all $k\ge0$ that
  \begin{equation*}
    \Exp{\psi_\lambda(x_{k+1})} \le \Exp{\psi_\lambda(x_k)} + 2\rho\eta_x\hat{\Delta}_k - \frac{\eta_x}{2}\Exp{\Vert \nabla \psi_\lambda(x_k) \Vert^2} + 4\rho\eta_x^2(L^2+\sigma^2)
  \end{equation*}
  where $\hat{\Delta}_k := \Exp{\psi(x_k) - \Psi(x_k, y_k)}$.
\end{lemma}

\begin{proof}
  Let $k\ge0$ be arbitrary but fixed. It follows easily from~\eqref{eq:bounded-variance-subgradient} that
  \begin{equation}
    \label{eq:steiner}
    \Exp{\Vert g_k^\xi \Vert^2} \le \Exp{\Vert g_k \Vert^2} + \sigma^2 \le L^2 + \sigma^2,
  \end{equation}
  where $\Exp{g_k^\xi}=g_k \in \partial_x\Phi(x_k,y_k)$.
  The definition of the Moreau envelope yields
  \begin{equation}
    \label{eq:defin-moreau}
    \Exp{g_\lambda(x_{k+1})} \le \Exp{\psi(\hat{x}_k)} + \frac{1}{2\lambda}\Exp{\Vert \hat{x}_k - x_{k+1} \Vert^2}.
  \end{equation}
  Similarly to Lemma~\ref{lem:descent-on-moreau} we deduce that for $v_k\in \partial\phi(\hat{x}_k)$ (as given in Lemma~\ref{lem:xhatk-as-prox}) and $\beta=1-\eta_x \lambda^{-1}$
  \begin{equation*}
    \begin{aligned}
      \Vert\hat{x}_k - x_{k+1} \Vert^2 %&= \Vert \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + \beta\hat{x}_k} - \prox{\eta_x f}{x_k - \eta_x g_k^\xi}\Vert^2 \\
       %&\le \Vert \beta(\hat{x}_k - x_k) + \eta_x (g_k^\xi - v_k)\Vert^2 \\
       &= {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x \beta\langle g_k^\xi - v_k, \hat{x}_k - x_k\rangle
       + \eta_x^2\Vert g_k^\xi - v_k \Vert^2.
    \end{aligned}
  \end{equation*}
  By applying the conditional expectation $\Expcond{\cdot}{x_k,y_k}$, then the unconditional one and using~\eqref{eq:steiner}, we get that
  \begin{equation*}
    \Exp{\Vert \hat{x}_k - x_{k+1} \Vert^2} \le \Exp{\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x(1-\frac{\eta_x}{\lambda}) \langle g_k-v_k, \hat{x}_k - x_k\rangle} + 4\eta_x^2(L^2+\sigma^2).
  \end{equation*}
  where $g_k= \Exp{g_k^\xi}$.
  Lastly, we combine the above inequality with~\eqref{eq:defin-moreau} and the estimate for the inner product~\eqref{eq:estimate-middle} as in Lemma~\ref{lem:descent-on-moreau} to deduce the statement of the lemma.
\end{proof}

\begin{lemma}%
  \label{lem:stoch-standard-gradient-ascent-estimation}
  With $\eta_y\le \nicefrac{1}{2L_{\nabla\Phi}}$ we have for all $k\ge0$ and all $y \in \R^n$
  \begin{equation}
    \label{eq:stoch-gradient-ascent-estimation}
    \begin{aligned}
      \MoveEqLeft \Exp{\Psi(x_{k+1}, y) - \Psi(x_{k+1}, y_{k+1})} \le  \frac{1}{2\eta_y} \Big(\Exp{\Vert y^*_m - y_k \Vert^2 - \Vert y^*_m - y_{k+1} \Vert^2} \Big) + \eta_y\sigma^2.
    \end{aligned}
  \end{equation}
\end{lemma}

\begin{proof}
  Let $k\ge0$ and $y\in\R^n$ be arbitrary but fixed.
  % By the definition of $y_{k+1}$ we have that
  % \begin{equation*} y_{k+1} = \argmin_{y\in\R^n} \Big\{ h(y) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y-y_k\rangle + \frac{1}{2\eta_y}\Vert y-y_k \Vert^2 \Big\}.
  % \end{equation*}
  As in Lemma~\ref{lem:standard-gradient-ascent-estimation}, we deduce
  \begin{equation*}
    % \label{eq:stoch-decrease}
    \begin{aligned}
      h(y_{k+1}) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y_{k+1}-y_k \rangle + \frac{1}{2\eta_y} \Big(\Vert y_{k+1} -y_k \Vert^2 + \Vert y-y_{k+1} \Vert^2 \Big)  \\
      \le h(y) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y-y_k \rangle + \frac{1}{2\eta_y} \Vert y-y_k \Vert^2.
    \end{aligned}
  \end{equation*}
  The term $\langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y_{k+1}-y_k \rangle$ is problematic, because the right~hand side of the inner product is not measurable with respect to the sigma algebra generated by past iterates $\mathcal{F}_k := \sigma\{x_{k+1},\dots, x_1, y_k, \dots, y_1\}$, so we insert and subtract $\langle \nabla_y\Phi(x_{k+1},y_k) , y_{k+1}-y_k\rangle$
  % to deduce
  % \begin{multline*}
  %     h(y_{k+1}) + \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k),y-y_k\rangle + \frac{1}{2\eta_y} \Vert y_{k+1} -y_k \Vert^2 + \frac{1}{2\eta_y} \Vert y-y_{k+1} \Vert^2 \\
  %     \le h(y) + \langle \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle  + \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle + \frac{1}{2\eta_y} \Vert y-y_k \Vert^2.
  % \end{multline*}
  Now, using Young's inequality we estimate the resulting inner product
  \begin{multline*}
    % \label{eq:young2}
    \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle \\
    \le \eta_y\Vert \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_{y}\Phi(x_{k+1},y_k) \Vert^2 + \frac{1}{4\eta_y} \Vert y_{k+1} - y_k \Vert^2.
  \end{multline*}
  Combining the above two inequalities for $y=y^*_m$ with $1\le m\le k$ and taking the expectation together with the bounded variance assumption~\eqref{eq:bounded-variance} gives
  \begin{equation}
    \label{eq:ab1}
    \begin{aligned}
    \MoveEqLeft \Exp{\Expcond{\langle \nabla_{y}\Phi(x_{k+1},y_k;\xi_k), y^*_m-y_k \rangle}{\mathcal{F}_k}}  + \Exp{h(y_{k+1})+ \frac{1}{2\eta_y} \Vert y^*_m-y_{k+1} \Vert^2}\\
    &\le  \Exp{\langle \nabla_{y}\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle - \frac{1}{4\eta_y} \Vert y_{k+1} -y_k \Vert^2}
    \\
    &\quad+ \eta_y \sigma^2+ \Exp{h(y^*_m) +\frac{1}{2\eta_y} \Vert y^*_m-y_k \Vert^2}.
    \end{aligned}
  \end{equation}
  From the descent lemma (in ascent form) and the fact that $ \eta_y \le  \nicefrac{1}{2L_{\nabla\Phi}}$ we have
  \begin{equation*}
    % \label{eq:stoch-ascent-lemma}
    \Phi(x_{k+1}, y_k) + \langle y_{k+1} - y_k, \nabla_y\Phi(x_{k+1}, y_k)\rangle - \frac{1}{4\eta_y} \Vert y_{k+1} - y_k \Vert^2 \le \Phi(x_{k+1}, y_{k+1}).
  \end{equation*}
  We plug the above inequality into~\eqref{eq:ab1}, make use of the concavity and add $f(x_{k+1})$ on both sides to deduce the statement of the lemma.
\end{proof}

\begin{lemma}%
  \label{lem:stoch-estimate-Delta}
  For all $1 \le m \le k$, we have that
  \begin{equation}
    \label{eq:stoch-estimate-Delta}
    \begin{aligned}
      \MoveEqLeft \hat{\Delta}_k \le 2\eta_x L(L_f+L+\sigma)(k-m) + \frac{1}{2\eta_y} \Exp{\Vert y_{k-1} - y^*_m \Vert^2 - \Vert y_k - y^*_m \Vert^2} + \eta_y\sigma^2.
    \end{aligned}
  \end{equation}
\end{lemma}

\begin{proof}
  Let the numbers $1 \le m \le k$ be fixed.
  Starting from the definition of $\hat{\Delta}_k$, we add~\eqref{eq:stoch-gradient-ascent-estimation} to obtain
  % NOTE: Consider using $k\ge1$ and get rid of the +1 everywhere
  \begin{equation}
    \label{eq:diff-function-values-stoch}
    \begin{aligned}
      \hat{\Delta}_k &= \Exp{\psi(x_k) - \Psi(x_k,y_k)} \\
      &\le \Exp{\psi(x_k) - \Psi(x_k, y^*_m)} + \frac{1}{2\eta_y} \Big(\Exp{\Vert y^*_m - y_{k-1} \Vert^2 - \Vert y^*_m - y_k \Vert^2} \Big)+ \eta_y\sigma^2.
    \end{aligned}
  \end{equation}
  As in~\eqref{eq:plus-minus-functionval} we deduce that
  \begin{equation*}
    % \label{eq:stoch-plus-minus}
    \Psi(x_k, y^*_k) - \Psi(x_k, y^*_m) \le \Phi(x_k,y_k^*) -\Phi(x_m,y_k^*) +\Phi(x_m,y_m^*) -\Phi(x_k,y_m^*).
  \end{equation*}
  Together with the $L$-Lipschitz continuity of $\Phi(\cdot, y)$ and~\eqref{eq:bound-prox-f} we estimate for $k\ge m$ as in~\eqref{eq:fun-val-same-y}, but using $\Exp{\Vert g_l^\xi \Vert}\le L + \sigma$,
  \begin{equation*}
    \begin{aligned}
      \Exp{\Phi(x_k, y^*_k) - \Phi(x_m, y^*_k)}
      %&\le L \Exp{\Vert x_k-x_m \Vert} \le L \sum_{l=m}^{k-1}\Exp{\Vert x_{l+1} - x_l \Vert} \\
      %&\le L \sum_{l=m}^{k-1} \Exp{\Vert \prox{\eta_x f}{x_l -\eta_x g_l^\xi} - \prox{\eta_x f}{x_l} \Vert+ \Vert \prox{\eta_x f}{x_l} - x_l \Vert} \\
      &\le \eta_x L\Big(L_f+\sqrt{L^2+\sigma^2}\Big)(k-m).
    \end{aligned}
  \end{equation*}
  % For $k=m$ the statement follows trivially.
  % Analogously,
  % \begin{equation*}
  %   \Exp{\Phi(x_m, y^*_m) - \Phi(x_k, y^*_m)} \le L \Exp{\Vert x_k - x_m \Vert} \le \eta_x L\Big(L_f+\sqrt{L^2+\sigma^2}\Big)(k-m).
  % \end{equation*}
  Plugging all of these into~\eqref{eq:diff-function-values-stoch} gives the statement of the lemma.
\end{proof}

