  \begin{equation}
    \label{eq:diff-function-values-stoch}
    \begin{aligned}
      \hat{\Delta}_k &= \Exp{\psi(x_k) - \Psi(x_k,y_k)} \\
      &\le \Exp{\psi(x_k) - \Psi(x_k, y^*_m)} + \frac{1}{2\eta_y} \Big(\Exp{\Vert y^*_m - y_{k-1} \Vert^2 - \Vert y^*_m - y_k \Vert^2} \Big)+ \eta_y\sigma^2.
    \end{aligned}
  \end{equation}
  As in~\eqref{eq:plus-minus-functionval} we deduce that
  \begin{equation*}
    % \label{eq:stoch-plus-minus}
    \Psi(x_k, y^*_k) - \Psi(x_k, y^*_m) \le \Phi(x_k,y_k^*) -\Phi(x_m,y_k^*) +\Phi(x_m,y_m^*) -\Phi(x_k,y_m^*).
  \end{equation*}
  Together with the $L$-Lipschitz continuity of $\Phi(\cdot, y)$ and~\eqref{eq:bound-prox-f} we estimate for $k\ge m$ as in~\eqref{eq:fun-val-same-y}, but using $\Exp{\Vert g_l^\xi \Vert}\le L + \sigma$,
  \begin{equation*}
    \begin{aligned}
      \Exp{\Phi(x_k, y^*_k) - \Phi(x_m, y^*_k)}
      %&\le L \Exp{\Vert x_k-x_m \Vert} \le L \sum_{l=m}^{k-1}\Exp{\Vert x_{l+1} - x_l \Vert} \\
      %&\le L \sum_{l=m}^{k-1} \Exp{\Vert \prox{\eta_x f}{x_l -\eta_x g_l^\xi} - \prox{\eta_x f}{x_l} \Vert+ \Vert \prox{\eta_x f}{x_l} - x_l \Vert} \\
      &\le \eta_x L\Big(L_f+\sqrt{L^2+\sigma^2}\Big)(k-m).
