  \end{equation*}
  % For $k=m$ the statement follows trivially.
  % Analogously,
  % \begin{equation*}
  %   \Exp{\Phi(x_m, y^*_m) - \Phi(x_k, y^*_m)} \le L \Exp{\Vert x_k - x_m \Vert} \le \eta_x L\Big(L_f+\sqrt{L^2+\sigma^2}\Big)(k-m).
