\begin{equation}
  \label{eq:minimax}
  \min_{x\in\R^d} \max_{y\in\R^n}\, \Big\{\Psi(x,y):=f(x) + \Phi(x,y) - h(y)\Big\}
  % \min_{x\in\R^d} \Big\{f(x) + \max_{y\in\R^n}\, \{\psi(x,y):= \Phi(x,y) - h(y)\}\Big\}
\end{equation}

\begin{equation}
  \label{eq:max-function}
  \phi(x) := \max_{y\in\R^n}\, \Phi(x,y) - h(y),\quad \text{where $\phi: \R^d \to \R$}.
\end{equation}

\begin{equation*}
  \psi := \phi+f, \quad \text{where $\psi:\R^d \to \R \cup\{+\infty\}$}.
\end{equation*}

For some $\rho \ge 0$, we say that
\begin{equation*}
  \label{eq:weakly_convex}
  \mbox{$\psi:\R^d \to \R\cup\{+\infty\}$ is \emph{$\rho$-weakly convex} if $\psi + (\rho/2) \Vert \cdot \Vert^2$ is convex.}
\end{equation*}
An example of a weakly convex function is one which is differentiable and the gradient is uniformly Lipschitz continuous with constant $L$ (we call such a function $L$-smooth). In this case, the weak convexity parameter $\rho$ is given by the Lipschitz constant.

For a proper, $\rho$-weakly convex and l.s.c.\ function $\psi: \R^d \rightarrow \R\cup\{+\infty\}$, the Moreau envelope of $\psi$ with the parameter $\lambda \in (0,\rho^{-1})$ is the function from $\R^d$ to $\R$ defined by
\begin{equation*}
  \label{eq:moreau}
  \psi_\lambda(x) := \inf_{z \in \R^d} \Big\{ \psi(z) + \frac{1}{2\lambda}\Vert z-x \Vert^2\Big\}.
\end{equation*}
The proximal operator of the function $\lambda \psi$ is the $\arg\min$ of the right-hand side in this definition, that is,
\begin{equation}
  \label{eq:prox}
  \prox{\lambda \psi}{x} := \argmin_{z \in \R^d}\Big\{ \psi(z) + \frac{1}{2\lambda}\Vert z-x \Vert^2\Big\}.
\end{equation}
Note that $\prox{\lambda \psi}{x}$ is uniquely defined by~\eqref{eq:prox} because the function being minimized is proper, l.s.c.\ and strongly convex.

% TODO: consider moving this paragraph past the definition of \epsilon-Stationarity??!!
For a function $\psi:\R^d \to \R\cup\{+\infty\}$ and a point $\bar{x}$ such that $\psi(\bar{x})$ is finite, the \emph{Fr\'echet subdifferential} of $\psi$ at $\bar{x}$, denoted by $\partial \psi(\bar{x})$, is the set of all vectors $v \in \R^d$ such that
\begin{equation*}
  \label{eq:subgradient}
  \psi(x) \ge \psi(\bar{x}) + \langle v, x- \bar{x}\rangle + o(\Vert x-\bar{x} \Vert) \quad \text{as $x \to \bar{x}$}.
\end{equation*}
For weakly convex function the Fr\'echet subdifferential can simply be expressed in terms of the convex subdifferential of the (convex) function $\psi+ (\rho/2)\Vert \cdot \Vert^2$.

The Moreau envelope allows us to naturally define a notion of \emph{near stationarity} even for nonsmooth and $\rho$-weakly convex functions.
% We say that a point $\bar{x}$ is stationary for a function if the Fr\'echet subdifferential of the function contains $0$ at $\bar{x}$. The concept of \emph{nearly stationary} is not quite as straightforward. We will use the norm of the gradient of the Moreau envelope as a proxy.
We say that for an $\epsilon>0$ and a $\lambda\in(0,\rho^{-1})$
\begin{equation}
  \label{eq:epsilon-stationary}
  \mbox{a point $x$ is $\epsilon$-\emph{stationary} for $\psi$ if $\Vert \nabla \psi_\lambda(x) \Vert \le \epsilon$}.
\end{equation}
Canonically, we call a point stationary if the above holds for $\epsilon=0$.

We discuss the stochastic version of problem~\eqref{eq:minimax} where the coupling function $\Phi$ is actually given as an expectation,
\begin{equation*}
  \Phi(x,y) = \E_{\xi\sim\mathcal{D}}\left[ \Phi(x,y;\xi)\right] \quad \forall (x,y)\in\R^d\times\R^n
\end{equation*}
and we can only access independent samples of the gradient $\nabla_x\Phi(x,y;\xi)$ (or subgradient) and $\nabla_y\Phi(x,y;\zeta)$, where $\xi$ and $\zeta$ are drawn from the (in general unknown) distribution $\mathcal{D}$.

\begin{assumption}[unbiased]%
  \label{ass:unbiased}
  The stochastic gradient estimator is unbiased, i.e.
  \begin{equation*}
    \Exp{\nabla\Phi(x,y;\xi)} = \nabla\Phi(x,y) \quad \forall (x,y)\in \R^d\times \R^n,
  \end{equation*}
  or in the case of subgradients
  \begin{equation*}
    \Exp{g^\xi} \in \partial [\Phi(\cdot,y)](x), \quad\text{where $g^\xi \in \partial [\Phi(\cdot,y;\xi)](x)$}.
  \end{equation*}
\end{assumption}

\begin{assumption}[bounded variance]%
  \label{ass:bounded-variance}
  The variance of the estimator is uniformly bounded, i.e.\ for all $(x,y)\in\R^d\times\R^n$ and a variance $\sigma^2\ge0$ we have
  \begin{equation}
    \label{eq:bounded-variance}
    \Exp{\Vert \nabla\Phi(x,y;\xi) - \nabla\Phi(x,y) \Vert^2} \le \sigma^2.
  \end{equation}
  In the setting of Section~\ref{sec:non-strongly-concave} where $\Phi$ is not necessarily smooth in the first component, we make the analogous assumption for subgradients, i.e.\
  \begin{equation}
    \label{eq:bounded-variance-subgradient}
    \Exp{\left\Vert g^\xi-\Exp{g^\xi}  \right\Vert^2} \le \sigma^2,
  \end{equation}
  for a stochastic subgradient $g^\xi\in \partial[\Phi(\cdot,y;\xi)](x)$.
\end{assumption}

\begin{assumption}%
  \label{ass:weakly-convex-gradient-lipschitz}
  The coupling function $\Phi$ is
  \begin{enumerate}
    \item[(i)]
      concave and $L_{\nabla\Phi}$-smooth in the second component uniformly in $x$,
      \begin{equation*}
        \Vert \nabla_y\Phi (x,y) - \nabla_y\Phi(x, y') \Vert \le L_{\nabla\Phi} \Vert y - y' \Vert \quad \forall x \in \R^d \, \forall y,y' \in \R^n.
      \end{equation*}
      \item[(ii)]
        $\rho$-weakly convex in the first component uniformly in the second one, i.e.
        \begin{equation*}
          \Phi(\cdot,y) + \frac{\rho}{2}\Vert \cdot \Vert^2 \quad \text{is convex for all $y\in\R^n$}.
        \end{equation*}
  \end{enumerate}
\end{assumption}

\begin{assumption}%
  \label{ass:max-function-lower-bounded}
  The function $\psi$ is lower bounded, i.e.\ $\inf_{x\in\R^d}\, \psi(x) > -\infty$.
\end{assumption}

In Section~\ref{sec:non-strongly-concave} we will actually need to bound the Moreau envelope $\psi_\lambda$, but these two conditions are in fact equivalent as for all $x\in\R^d$ and any $\lambda\in (0,\rho^{-1})$
\begin{equation*}
  \psi(x) \ge \psi_\lambda(x) \ge \inf_{u\in\R^d}\, \psi(u).
\end{equation*}

\begin{assumption}%
  \label{ass:lipschitz}
  $\Phi$ is $L$-Lipschitz in the first component uniformly over $\dom h$ in the second one, i.e.
  \begin{equation*}
    \Vert \Phi(x, y) - \Phi(x', y) \Vert \le L \Vert x - x' \Vert \quad \forall x,x' \in \R^d\; \forall y \in \dom h.
  \end{equation*}
\end{assumption}

\begin{assumption}%
  \label{ass:regularizers}
  The regularizers $f$ and $h$ are proper, l.s.c.\ and convex
  \begin{enumerate}
    \item[(i)]
      Additionally, $f$ is either $L_f$-Lipschitz continuous on its domain, which is assumed to be open, or the indicator of a nonempty, convex and closed set.
      Either of those assumptions guarantees for any $\gamma>0$ the bound
      \begin{equation}
        \label{eq:bound-prox-f}
        \Vert \prox{\gamma f}{x}-x \Vert \le \gamma L_f \quad \forall x \in \dom f.
      \end{equation}
    \item[(ii)]
    Furthermore, $h$ has a bounded domain $\dom h$ such that the diameter of $\dom h$ is bounded by $D_h$.
  \end{enumerate}
\end{assumption}

This implies that for every $x\in\R^d$ the set
\begin{equation}
  \label{eq:solution-set-mapping}
  Y(x) := \Big\{y^* \in \R^n : \phi(x) = \Phi(x,y^*) -h(y^*) = \max_{y\in\R^n} \{\Phi(x,y)-h(y)\} \Big\}
\end{equation}

For initial values $(x_0,y_0)\in \dom f \times \dom h$ the deterministic version of alternating GDA, for $g_k \in \partial [\Phi(\cdot,y_k)](x_k)$, reads as
\begin{equation}%
  \label{eq:alt-gda-non-strongly}
  (\forall k \ge 0)
  \left\lfloor
    \begin{array}{l}
      x_{k+1} = \prox{\eta_x f}{x_k - \eta_x g_k} \\
      y_{k+1} = \prox{\eta_y h}{y_k + \eta_y \nabla_y\Phi(x_{k+1},y_k)}.
    \end{array}\right.
\end{equation}

For initial values $(x_0,y_0)\in \dom f \times \dom h$ the stochastic version of alternating GDA is given by
\begin{equation}%
  \label{eq:gda-non-strongly-stoch}
  (\forall k\ge 0)
  \left\lfloor
    \begin{array}{l}
      x_{k+1} = \prox{\eta_x f}{x_k - \eta_x g_k^\xi} \\
      y_{k+1} = \prox{\eta_y h}{y_k + \eta_y \nabla_y\Phi(x_{k+1},y_k;\zeta_k)},
    \end{array}\right.
\end{equation}

\begin{lemma}[{see~\cite[Theorem 3.52]{mordukhovich-variational-analysis}}]%
  \label{lem:lipschitz-bounded-subgradients}
  For an $L_\psi$-Lipschitz continuous function $\psi:\R^d \to \R$ every Fr\'echet subgradient is bounded in norm by $L_\psi$.
\end{lemma}

\begin{lemma}[{see~\cite[Lemma 2.2]{stoch_weakly_model_based}}]%
  \label{lem:grad_smooth_is_prox}
  Let $\psi: \R^d \to \R\cup\{+\infty\}$ be a proper, $\rho$-weakly convex, and l.s.c.\ function, and let $\lambda \in (0,\rho^{-1})$. Then the Moreau envelope $\psi_\lambda$ is continuously differentiable
  on $\R^d$ with gradient
  \begin{equation*}
    \nabla \psi_\lambda(x) = \frac{1}{\lambda}\left(x - \prox{\lambda \psi}{x}\right) \quad \mbox{for all $x \in \R^d$},
  \end{equation*}
  and this gradient is Lipschitz continuous.
\end{lemma}

\begin{proposition}[Subgradient characterization of the max function]%
  \label{thm:extended-danskin}
  Let Assumption~\ref{ass:weakly-convex-gradient-lipschitz} and~\ref{ass:regularizers} hold true.
  Then, the function $\phi$, see~\eqref{eq:max-function}, fulfills
  \begin{equation*}
    \partial [\Phi(\cdot,y^*)](x) \subseteq \partial\phi(x) \quad \forall y^*\in Y(x), \forall x\in \R^d.
  \end{equation*}
  In particular, $\phi$ is $\rho$-weakly convex.
\end{proposition}

\begin{proof}
  From the $\rho$-weak convexity of $\Phi(\cdot,y)$, we have that $\Phi(\cdot,y) + \frac{\rho}{2} \|\cdot\|^2$ is convex for all $y\in\R^n$. We define $\tilde{\Phi}(x,y) = \Phi(x,y) + \frac\rho2 \|x\|^2$ and $\tilde{\Gamma}(x,y) = \Gamma(x,y)+\frac{\rho}{2}\Vert x \Vert^2$ for $(x,y)\in\R^d\times\R^n$ as well as
  \begin{equation*}
    \tilde{\phi}(x) = \max_{y \in \R^n} \tilde{\Gamma}(x,y) = \phi(x) + \frac{\rho}{2} \|x\|^2.
  \end{equation*}
  Notice that $\tilde{\Gamma}(x,\cdot)$ is concave for any $x \in \R^d$ and $\tilde{\Gamma}(\cdot,y)$ is convex for any $y \in \R^n$.
  Thus, the function $\tilde{\phi}$ is convex and $\dom \tilde{\phi} = \dom \phi = \R^d$. Therefore $\phi$ is continuous, which implies that $\partial \phi(x) \neq \emptyset$ for any $x \in \R^d$.
  Let $x \in \R^d$, $y \in Y(x)$ and $v \in \R^d$. For any $\alpha >0$ it holds
  \begin{equation*}
    \frac{\tilde{\phi}(x+\alpha v) - \tilde{\phi}(x)}{\alpha} \geq \frac{\tilde{\Gamma}(x+\alpha v, y) - \tilde{\Gamma}(x,y)}{\alpha} =  \frac{\tilde{\Phi}(x+\alpha v, y) - \tilde{\Phi}(x,y)}{\alpha},
  \end{equation*}
  thus
  \begin{equation}
    \begin{aligned}
      \tilde{\phi}'(x;v) &= \inf_{\alpha >0} \frac{\tilde{\phi}(x+\alpha v) - \tilde{\phi}(x)}{\alpha} \geq \inf_{\alpha >0} \frac{\tilde{\Phi}(x+\alpha v, y) - \tilde{\Phi}(x,y)}{\alpha} = [\tilde{\Phi}(\cdot,y)]'(x;v),
    \end{aligned}
  \end{equation}
  where $[\Phi(\cdot,y)]'(x;v)$ denotes the directional derivative of $\Phi$ in the first component at $x$ in the direction $v$.
  In conclusion,
  \begin{equation}
    \label{eq1}
    \tilde{\phi}'(x;v) \geq \sup_{y \in Y(x)}  [\tilde{\Phi}(\cdot,y)]'(x;v) \quad \forall v \in \R^d
  \end{equation}
  and for $y\in Y(x)$ we therefore conclude $\partial [\tilde{\Phi}(\cdot,y)](x) \subseteq \partial\tilde{\phi}(x)$.
  The first statement is obtained by subtracting $\rho x$ on both sides of the inclusion.
\end{proof}

