  \begin{equation*}
      0 \in \partial \psi(\hat{x}_k) + \frac1\lambda(\hat{x}_k-x_k) = \partial(\phi+f)(\hat{x}_k) + \frac1\lambda(\hat{x}_k-x_k).
  \end{equation*}
