\begin{lemma}%
  \label{lem:descent-on-moreau}
  With $\lambda = \nicefrac{1}{2\rho}$ and $\eta_x \ge 0$ we have for all $k\ge0$ that
  \begin{equation*}
    \psi_\lambda(x_{k+1}) \le \psi_\lambda(x_k) + 2\rho\eta_x\Delta_k - \frac12\eta_x \Vert \nabla \psi_\lambda(x_k) \Vert^2  + 4\rho\eta_x^2L^2,
  \end{equation*}
  where $\Delta_k := \psi(x_k) - \Psi(x_k, y_k) \ge 0$.
\end{lemma}

\begin{proof}
  Let $k\ge0$ be fixed. As before we denote $\hat{x}_k = \prox{\lambda \psi}{x_k}$. From the definition of the Moreau envelope we have that
  \begin{equation}
    \label{eq:moreau-is-min}
    \psi_\lambda(x_{k+1}) = \min_{x\in\R^d} \Big\{ \psi(x) + \frac{1}{2\lambda} \Vert x - x_{k+1} \Vert^2\Big\} \le \psi(\hat{x}_k) + \frac{1}{2\lambda} \Vert \hat{x}_k - x_{k+1} \Vert^2.
  \end{equation}
  Let now $v_k \in \partial\phi(\hat{x}_k)$ as in Lemma~\ref{lem:xhatk-as-prox}. We successively deduce for $\beta:=1-\eta_x \lambda^{-1}$
  \begin{align}
    \Vert \hat{x}_k - x_{k+1} \Vert^2 &= \Vert \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + \beta\hat{x}_k} - \prox{\eta_x f}{x_k - \eta_x g_k}\Vert^2 \label{eq:defin-iter}\\
     &\le \Vert \beta(\hat{x}_k - x_k) + \eta_x (g_k - v_k)\Vert^2 \label{eq:1-Lipschitz}\\
     &= {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x\beta\langle g_k-v_k, \hat{x}_k - x_k\rangle
     + \eta_x^2\Vert g_k - v_k \Vert^2 \notag\\
     &\le {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x \beta\langle g_k-v_k, \hat{x}_k - x_k\rangle + 4\eta_x^2L^2 \label{eq:Lipschitz}
  \end{align}
  where~\eqref{eq:defin-iter} uses Lemma~\ref{lem:xhatk-as-prox} and the definition of $x_{k+1}$, inequality~\eqref{eq:1-Lipschitz} holds because of the nonexpansiveness of the proximal operator, and~\eqref{eq:Lipschitz} follows from the Lipschitz continuity of $\Phi$ and $\phi$ (see Lemma~\ref{lem:max-is-lipschitz}) and the fact that Lipschitz continuity implies bounded subgradients.
  We are left with estimating the inner product in the above inequality and we do so by splitting it into two:
  first of all, from the weak convexity of $\Phi$ in $x$ we have that
  \begin{equation*}
    \begin{aligned}
      \langle g_k, \hat{x}_k - x_k \rangle &\le \Phi(\hat{x}_k, y_k) - \Phi(x_k, y_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2 \\
      % &= \Phi(\hat{x}_k, y_k)-h(y_k) - (\Phi(x_k, y_k)-h(y_k)) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2\\
      &\le \phi(\hat{x}_k) - \Gamma(x_k,y_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2.
    \end{aligned}
  \end{equation*}
  Secondly, by the $\rho$-weak convexity of $\phi$
  \begin{equation*}
    -\langle v_k, \hat{x}_k - x_k\rangle \le \phi(x_k) - \phi(\hat{x}_k) + \frac{\rho}{2} \Vert \hat{x}_k - x_k \Vert^2.
  \end{equation*}
  Combining the last two inequalities we get that
  \begin{equation}
    \label{eq:estimate-middle}
    \langle g_k-v_k, \hat{x}_k - x_k\rangle \le \phi(x_k) - \Gamma(x_k,y_k) + \rho \Vert \hat{x}_k - x_k \Vert^2.
  \end{equation}
  Plugging~\eqref{eq:estimate-middle} into~\eqref{eq:Lipschitz} we deduce
  \begin{equation}
    \begin{aligned}
    \label{eq:ab3}
    \Vert \hat{x}_k - x_{k+1} \Vert^2 \le \underbrace{[{(1-\eta_x\lambda^{-1})}^2+2\eta_x(1-\eta_x \lambda^{-1})\rho]}_{= (*)} \Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x \Delta_k + 4\eta_x^2L^2, \\
    % &\le \Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x\Delta_k -2\eta_x\rho \Vert\hat{x}_k - x_k \Vert^2  + 2\eta_x^2 L^2
    \end{aligned}
  \end{equation}
  where we used the fact that $1-\beta\le1$ in the factor of $\Delta_k$.
  Now note that
  \begin{equation}
    \label{eq:terrible-algebra}
    \begin{aligned}
      (*) &= 1 - 2\eta_x \lambda^{-1} + \eta_x^2 \lambda^{-2} + 2\eta_x\rho - 2\eta_x^2 \lambda^{-1}\rho\\
      &= 1 - 4\eta_x\rho + 4 \eta_x^2\rho^2 + 2\eta_x\rho - 4 \eta_x^2\rho^2 = 1-2\eta_x\rho.
    \end{aligned}
  \end{equation}
  Combining~\eqref{eq:moreau-is-min},~\eqref{eq:ab3} and~\eqref{eq:terrible-algebra} we deduce, using $\lambda=\nicefrac{1}{2\rho}$,
  % a lot of algebra happens here but it's correct
  \begin{equation*}
    \label{eq:descent-moreau}
    \begin{aligned}
      \psi_\lambda(x_{k+1}) &\le \psi(\hat{x}_k) + \frac{1}{2\lambda} \left(\Vert \hat{x}_k - x_k \Vert^2 + 2\eta_x\Delta_k -2\eta_x\rho \Vert\hat{x}_k - x_k \Vert^2  + 4\eta_x^2L^2\right) \\
      &= \psi_\lambda(x_k) + 2\rho\eta_x\Delta_k - \frac12\eta_x \Vert \nabla \psi_\lambda(x_k) \Vert^2  + 4\rho\eta_x^2L^2.
    \end{aligned}
  \end{equation*}
  % where we used that $\lambda=\nicefrac{1}{2\rho}$.
\end{proof}

Let $k\ge0$ be fixed. As before we denote $\hat{x}_k = \prox{\lambda \psi}{x_k}$. From the definition of the Moreau envelope we have that
\begin{equation}
  \label{eq:moreau-is-min}
  \psi_\lambda(x_{k+1}) = \min_{x\in\R^d} \Big\{ \psi(x) + \frac{1}{2\lambda} \Vert x - x_{k+1} \Vert^2\Big\} \le \psi(\hat{x}_k) + \frac{1}{2\lambda} \Vert \hat{x}_k - x_{k+1} \Vert^2.
\end{equation}

Let now $v_k \in \partial\phi(\hat{x}_k)$ as in Lemma~\ref{lem:xhatk-as-prox}. We successively deduce for $\beta:=1-\eta_x \lambda^{-1}$
\begin{align}
  \Vert \hat{x}_k - x_{k+1} \Vert^2 &= \Vert \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + \beta\hat{x}_k} - \prox{\eta_x f}{x_k - \eta_x g_k}\Vert^2 \label{eq:defin-iter}\\
   &\le \Vert \beta(\hat{x}_k - x_k) + \eta_x (g_k - v_k)\Vert^2 \label{eq:1-Lipschitz}\\
   &= {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x\beta\langle g_k-v_k, \hat{x}_k - x_k\rangle
