\begin{lemma}%
  \label{lem:stoch-descent-on-moreau}
  With $\lambda = \nicefrac{1}{2\rho}$ we have for all $k\ge0$ that
  \begin{equation*}
    \Exp{\psi_\lambda(x_{k+1})} \le \Exp{\psi_\lambda(x_k)} + 2\rho\eta_x\hat{\Delta}_k - \frac{\eta_x}{2}\Exp{\Vert \nabla \psi_\lambda(x_k) \Vert^2} + 4\rho\eta_x^2(L^2+\sigma^2)
  \end{equation*}
  where $\hat{\Delta}_k := \Exp{\psi(x_k) - \Psi(x_k, y_k)}$.
\end{lemma}

\begin{proof}
  Let $k\ge0$ be arbitrary but fixed. It follows easily from~\eqref{eq:bounded-variance-subgradient} that
  \begin{equation}
    \label{eq:steiner}
    \Exp{\Vert g_k^\xi \Vert^2} \le \Exp{\Vert g_k \Vert^2} + \sigma^2 \le L^2 + \sigma^2,
  \end{equation}
  where $\Exp{g_k^\xi}=g_k \in \partial_x\Phi(x_k,y_k)$.
  The definition of the Moreau envelope yields
  \begin{equation}
    \label{eq:defin-moreau}
    \Exp{g_\lambda(x_{k+1})} \le \Exp{\psi(\hat{x}_k)} + \frac{1}{2\lambda}\Exp{\Vert \hat{x}_k - x_{k+1} \Vert^2}.
  \end{equation}
  Similarly to Lemma~\ref{lem:descent-on-moreau} we deduce that for $v_k\in \partial\phi(\hat{x}_k)$ (as given in Lemma~\ref{lem:xhatk-as-prox}) and $\beta=1-\eta_x \lambda^{-1}$
  \begin{equation*}
    \begin{aligned}
      \Vert\hat{x}_k - x_{k+1} \Vert^2 %&= \Vert \prox{\eta_x f}{\eta_x\lambda^{-1}x_k - \eta_x v_k + \beta\hat{x}_k} - \prox{\eta_x f}{x_k - \eta_x g_k^\xi}\Vert^2 \\
       %&\le \Vert \beta(\hat{x}_k - x_k) + \eta_x (g_k^\xi - v_k)\Vert^2 \\
       &= {\beta}^2\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x \beta\langle g_k^\xi - v_k, \hat{x}_k - x_k\rangle
       + \eta_x^2\Vert g_k^\xi - v_k \Vert^2.
    \end{aligned}
  \end{equation*}
  By applying the conditional expectation $\Expcond{\cdot}{x_k,y_k}$, then the unconditional one and using~\eqref{eq:steiner}, we get that
  \begin{equation*}
    \Exp{\Vert \hat{x}_k - x_{k+1} \Vert^2} \le \Exp{\Vert \hat{x}_k - x_k \Vert^2 + 2 \eta_x(1-\frac{\eta_x}{\lambda}) \langle g_k-v_k, \hat{x}_k - x_k\rangle} + 4\eta_x^2(L^2+\sigma^2).
  \end{equation*}
  where $g_k= \Exp{g_k^\xi}$.
  Lastly, we combine the above inequality with~\eqref{eq:defin-moreau} and the estimate for the inner product~\eqref{eq:estimate-middle} as in Lemma~\ref{lem:descent-on-moreau} to deduce the statement of the lemma.
\end{proof}

