\begin{lemma}%
  \label{lem:stoch-standard-gradient-ascent-estimation}
  With $\eta_y\le \nicefrac{1}{2L_{\nabla\Phi}}$ we have for all $k\ge0$ and all $y \in \R^n$
  \begin{equation}
    \label{eq:stoch-gradient-ascent-estimation}
    \begin{aligned}
      \MoveEqLeft \Exp{\Psi(x_{k+1}, y) - \Psi(x_{k+1}, y_{k+1})} \le  \frac{1}{2\eta_y} \Big(\Exp{\Vert y^*_m - y_k \Vert^2 - \Vert y^*_m - y_{k+1} \Vert^2} \Big) + \eta_y\sigma^2.
    \end{aligned}
  \end{equation}
\end{lemma}

\begin{proof}
  Let $k\ge0$ and $y\in\R^n$ be arbitrary but fixed.
  % By the definition of $y_{k+1}$ we have that
  % \begin{equation*} y_{k+1} = \argmin_{y\in\R^n} \Big\{ h(y) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y-y_k\rangle + \frac{1}{2\eta_y}\Vert y-y_k \Vert^2 \Big\}.
  % \end{equation*}
  As in Lemma~\ref{lem:standard-gradient-ascent-estimation}, we deduce
  \begin{equation*}
    % \label{eq:stoch-decrease}
    \begin{aligned}
      h(y_{k+1}) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y_{k+1}-y_k \rangle + \frac{1}{2\eta_y} \Big(\Vert y_{k+1} -y_k \Vert^2 + \Vert y-y_{k+1} \Vert^2 \Big)  \\
      \le h(y) - \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y-y_k \rangle + \frac{1}{2\eta_y} \Vert y-y_k \Vert^2.
    \end{aligned}
  \end{equation*}
  The term $\langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k), y_{k+1}-y_k \rangle$ is problematic, because the right~hand side of the inner product is not measurable with respect to the sigma algebra generated by past iterates $\mathcal{F}_k := \sigma\{x_{k+1},\dots, x_1, y_k, \dots, y_1\}$, so we insert and subtract $\langle \nabla_y\Phi(x_{k+1},y_k) , y_{k+1}-y_k\rangle$
  % to deduce
  % \begin{multline*}
  %     h(y_{k+1}) + \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k),y-y_k\rangle + \frac{1}{2\eta_y} \Vert y_{k+1} -y_k \Vert^2 + \frac{1}{2\eta_y} \Vert y-y_{k+1} \Vert^2 \\
  %     \le h(y) + \langle \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle  + \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle + \frac{1}{2\eta_y} \Vert y-y_k \Vert^2.
  % \end{multline*}
  Now, using Young's inequality we estimate the resulting inner product
  \begin{multline*}
    % \label{eq:young2}
    \langle \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_y\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle \\
    \le \eta_y\Vert \nabla_y\Phi(x_{k+1},y_k;\zeta_k) - \nabla_{y}\Phi(x_{k+1},y_k) \Vert^2 + \frac{1}{4\eta_y} \Vert y_{k+1} - y_k \Vert^2.
  \end{multline*}
  Combining the above two inequalities for $y=y^*_m$ with $1\le m\le k$ and taking the expectation together with the bounded variance assumption~\eqref{eq:bounded-variance} gives
  \begin{equation}
    \label{eq:ab1}
    \begin{aligned}
    \MoveEqLeft \Exp{\Expcond{\langle \nabla_{y}\Phi(x_{k+1},y_k;\xi_k), y^*_m-y_k \rangle}{\mathcal{F}_k}}  + \Exp{h(y_{k+1})+ \frac{1}{2\eta_y} \Vert y^*_m-y_{k+1} \Vert^2}\\
    &\le  \Exp{\langle \nabla_{y}\Phi(x_{k+1},y_k), y_{k+1}-y_k \rangle - \frac{1}{4\eta_y} \Vert y_{k+1} -y_k \Vert^2}
    \\
    &\quad+ \eta_y \sigma^2+ \Exp{h(y^*_m) +\frac{1}{2\eta_y} \Vert y^*_m-y_k \Vert^2}.
    \end{aligned}
  \end{equation}
  From the descent lemma (in ascent form) and the fact that $ \eta_y \le  \nicefrac{1}{2L_{\nabla\Phi}}$ we have
  \begin{equation*}
    % \label{eq:stoch-ascent-lemma}
    \Phi(x_{k+1}, y_k) + \langle y_{k+1} - y_k, \nabla_y\Phi(x_{k+1}, y_k)\rangle - \frac{1}{4\eta_y} \Vert y_{k+1} - y_k \Vert^2 \le \Phi(x_{k+1}, y_{k+1}).
  \end{equation*}
  We plug the above inequality into~\eqref{eq:ab1}, make use of the concavity and add $f(x_{k+1})$ on both sides to deduce the statement of the lemma.
\end{proof}

Let $k\ge0$ and $y\in\R^n$ be arbitrary but fixed.
